use forge_domain :: { Context , Effort , ReasoningConfig , Transformer } ; use tracing :: warn ; use forge_domain :: { Context , Effort , ReasoningConfig , Temperature , TopK , TopP , Transformer } ; use pretty_assertions :: assert_eq ; use super :: * ; impl ModelSpecificReasoning { # [doc = " Creates a model-specific reasoning normalizer for the given model id."] pub (crate) fn new (model_id : impl Into < String >) -> Self { Self { model_id : model_id . into () } } fn family (& self) -> AnthropicModelFamily { let id = self . model_id . to_lowercase () ; if id . contains ("opus-4-7") || id . contains ("47-opus") { AnthropicModelFamily :: AdaptiveOnly } else if id . contains ("opus-4-6") || id . contains ("46-opus") || id . contains ("sonnet-4-6") || id . contains ("46-sonnet") { AnthropicModelFamily :: AdaptiveFriendly } else if id . contains ("opus-4-5") || id . contains ("45-opus") { AnthropicModelFamily :: LegacyWithEffort } else { AnthropicModelFamily :: LegacyNoEffort } } }